// GitHub -> CI health card, AS GRAPH SOURCE (#3650, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app real modules (the shared/ui
// design system + the store via appModules, the github lib/hook surface + planner board via the github
// graph-platform, and the sibling views as @/components/* graph records). Behaviour runs here.
// CI health card -- pass/fail matrix over the last 7 days per repo (#1644).
// Preview note: the `CiRow` type (githubSummary lib) is app-internal -- inlined below, with sample
// defaults so the card previews standalone.

import { Text } from "@/shared/ui/typography/Text";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Grid } from "@/shared/ui/layout/Grid";
import { Box } from "@/shared/ui/layout/Box";
import { Card } from "@/shared/ui/data/Card";
import { CardEmpty, SkeletonRows } from "@/shared/ui/feedback/CardStates";

interface CiRow { name: string; days: (boolean | null)[] }
const SAMPLE_MATRIX: CiRow[] = [
  { name: "design-studio", days: [true, true, false, true, true, true, true] },
  { name: "infra", days: [true, true, true, null, true, true, true] },
  { name: "docs", days: [null, null, true, true, true, true, true] },
];

export function CIHealthCard({ matrix = SAMPLE_MATRIX, loading = false }: {
  matrix?: CiRow[];
  loading?: boolean;
}) {
  if (loading && matrix.length === 0) {
    return (
      <Card style={{ padding: "14px 16px" }} title="CI health" hint="last 7 days . all branches" headMb={10}>
        <SkeletonRows rows={4} h={14} />
      </Card>
    );
  }
  if (matrix.length === 0) {
    return (
      <Card style={{ padding: "14px 16px" }} title="CI health" hint="last 7 days . all branches" headMb={10}>
        <CardEmpty icon="o" title="No CI runs found" hint="Workflow runs across your repos surface here." />
      </Card>
    );
  }
  return (
    <Card style={{ padding: "14px 16px" }} title="CI health" hint="last 7 days . all branches" headMb={10}>
      <Stack gap={6}>
        {matrix.map(({ name, days }) => (
          <Grid key={name} cols="80px 1fr 28px" gap={8} align="center">
            <Text mono size={10.5} tone="muted" style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{name}</Text>
            <Row gap={4} align="stretch">
              {days.map((d, i) => (
                <Box key={i} bg={d === null ? "var(--bg-elev2)" : d ? "var(--success)" : "var(--danger)"} radius={3} style={{
                  flex: 1, height: 14,
                  opacity: d === null ? 0.4 : 0.85,
                }} />
              ))}
            </Row>
            <Text mono size={10.5} tone="dim" style={{ textAlign: "right" }}>
              {days.filter((d) => d === true).length}{"/"}{days.filter((d) => d !== null).length}
            </Text>
          </Grid>
        ))}
      </Stack>
    </Card>
  );
}

export { CIHealthCard as GitHubCIHealth };
